  def resolve_rpc_reply(service, op, variant, payload)
    if service == "AuthService" && op == "begin-browser-login"
      case variant
      when "BeginBrowserLoginResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "get-act-as-scope-set"
      case variant
      when "ActAsScopeSetResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "exchange-act-as-credential"
      case variant
      when "ActAsTokenResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "login"
      case variant
      when "LoginResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "complete"
      case variant
      when "LoginResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "refresh"
      case variant
      when "LoginResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "logout"
      case variant
      when "EmptyResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "resume-session"
      case variant
      when "LoginResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "end-session"
      case variant
      when "EmptyResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "me"
      case variant
      when "MeResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "begin-cli-login"
      case variant
      when "BeginCliLoginResponse" then return payload
      when "ServiceError" then raise ServiceErrorRefusal.new(ServiceError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "AuthService" && op == "inspect-cli-login"
      case variant
